if($_SERVER['REQUEST_METHOD']==='POST'){
    $name=trim($_POST['full_name']??'');$email=strtolower(trim($_POST['email']??''));$phone=trim($_POST['phone']??'');$password=$_POST['password']??'';
    if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||$phone===''||strlen($password)<6){$error='Please provide a name, valid email, phone and a password of at least 6 characters.';}
    else{
        $c=$conn->prepare("SELECT user_id FROM users WHERE email=? OR phone=? LIMIT 1");$c->bind_param('ss',$email,$phone);$c->execute();
        if($c->get_result()->fetch_assoc()){$error='Email or phone number already exists.';}else{
            $hash=password_hash($password,PASSWORD_DEFAULT);$s=$conn->prepare("INSERT INTO users (full_name,email,phone,password_hash,role,is_active,created_at) VALUES (?,?,?,?, 'ADMIN', TRUE, NOW())");$s->bind_param('ssss',$name,$email,$phone,$hash);$s->execute();$message='New admin account created successfully.';
        }
    }
}
$name=$_SESSION['full_name']??'Admin';$initial=strtoupper(substr(trim($name),0,1));
